CREATE FUNCTION public.admin_verify_donor_identity(_email text,_cnp text,_remove boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin_national') THEN RAISE EXCEPTION 'Acces interzis'; END IF; IF char_length(_email)>255 OR _cnp !~ '^[1-9][0-9]{12}$' THEN RAISE EXCEPTION 'Date invalide'; END IF; SELECT id INTO target FROM auth.users WHERE lower(email)=lower(trim(_email)) AND email_confirmed_at IS NOT NULL; IF target IS NULL THEN RAISE EXCEPTION 'Contul trebuie să existe și să aibă emailul confirmat'; END IF; IF _remove THEN DELETE FROM public.donor_identities WHERE user_id=target; ELSE INSERT INTO public.donor_identities(user_id,cnp,verified_by) VALUES(target,_cnp,auth.uid()) ON CONFLICT(user_id) DO UPDATE SET cnp=EXCLUDED.cnp,verified_by=auth.uid(),verified_at=now(); END IF; INSERT INTO public.audit_log(user_id,action,table_name,record_id) VALUES(auth.uid(),CASE WHEN _remove THEN 'DONOR_IDENTITY_REVOKED' ELSE 'DONOR_IDENTITY_VERIFIED' END,'donor_identities',target); END; $$;
REVOKE ALL ON FUNCTION public.admin_verify_donor_identity(text,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_verify_donor_identity(text,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.is_published_media(_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.articles a WHERE a.status='publicat' AND (right(split_part(a.image_url,'?',1),length('/storage/v1/object/public/media/'||_name))='/storage/v1/object/public/media/'||_name OR right(split_part(a.image_url,'?',1),length('/storage/v1/object/sign/media/'||_name))='/storage/v1/object/sign/media/'||_name OR right(split_part(a.pdf_url,'?',1),length('/storage/v1/object/public/media/'||_name))='/storage/v1/object/public/media/'||_name OR right(split_part(a.pdf_url,'?',1),length('/storage/v1/object/sign/media/'||_name))='/storage/v1/object/sign/media/'||_name OR position('/storage/v1/object/public/media/'||_name in a.content)>0 OR position('/storage/v1/object/sign/media/'||_name in a.content)>0)) OR EXISTS(SELECT 1 FROM public.site_pages p WHERE p.status='publicat' AND (right(split_part(p.og_image,'?',1),length('/storage/v1/object/public/media/'||_name))='/storage/v1/object/public/media/'||_name OR right(split_part(p.og_image,'?',1),length('/storage/v1/object/sign/media/'||_name))='/storage/v1/object/sign/media/'||_name OR position('/storage/v1/object/public/media/'||_name in p.content)>0 OR position('/storage/v1/object/sign/media/'||_name in p.content)>0)); $$;